const takeManualSync = `-- name: TakeManualSync :one
WITH marked AS (
    SELECT p.id, p.manual_sync_time FROM pipelines p
    WHERE p.org_id = $1 AND p.id = $2 AND p.manual_sync_time IS NOT NULL
    FOR UPDATE
)
UPDATE pipelines u SET manual_sync_time = NULL
FROM marked
WHERE u.org_id = $1 AND u.id = marked.id
RETURNING marked.manual_sync_time > now() - interval '5 minutes' AS manual
`

type TakeManualSyncParams struct {
	OrgID uuid.UUID
	ID    uuid.UUID
}

// Whether the API just started this pipeline's sync by hand. RETURNING sees
// the row as updated, so the mark is read first.
func (q *Queries) TakeManualSync(ctx context.Context, arg TakeManualSyncParams) (bool, error) {
	row := q.db.QueryRow(ctx, takeManualSync, arg.OrgID, arg.ID)
	var manual bool
	err := row.Scan(&manual)
	return manual, err
}

const tryLockPlacement = `-- name: TryLockPlacement :one
SELECT pg_try_advisory_xact_lock(hashtextextended($1::text, 0))
`

// Passes of a data plane run one at a time, each until its transaction ends.
// False: another pass has it.
func (q *Queries) TryLockPlacement(ctx context.Context, dataPlane string) (bool, error) {
	row := q.db.QueryRow(ctx, tryLockPlacement, dataPlane)
	var pg_try_advisory_xact_lock bool
	err := row.Scan(&pg_try_advisory_xact_lock)
	return pg_try_advisory_xact_lock, err
}

const unfinishedWorkOfSyncs = `-- name: UnfinishedWorkOfSyncs :many
SELECT id FROM dispatches
WHERE org_id = $1 AND state <> 'finished' AND input->>'SyncID' = ANY($2::text[])
`

type UnfinishedWorkOfSyncsParams struct {
	OrgID   uuid.UUID
	SyncIds []string
}

// What the syncs have running or waiting, their post-sync steps included.
func (q *Queries) UnfinishedWorkOfSyncs(ctx context.Context, arg UnfinishedWorkOfSyncsParams) ([]string, error) {
	rows, err := q.db.Query(ctx, unfinishedWorkOfSyncs, arg.OrgID, arg.SyncIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const unwokenDispatches = `-- name: UnwokenDispatches :many
SELECT id, workflow_id FROM dispatches
WHERE org_id = $1 AND state = 'finished' AND NOT woken
ORDER BY finish_time
LIMIT $2
`

type UnwokenDispatchesParams struct {
	OrgID   uuid.UUID
	MaxRows int32
}

type UnwokenDispatchesRow struct {
	ID         string
	WorkflowID string
}

func (q *Queries) UnwokenDispatches(ctx context.Context, arg UnwokenDispatchesParams) ([]UnwokenDispatchesRow, error) {
	rows, err := q.db.Query(ctx, unwokenDispatches, arg.OrgID, arg.MaxRows)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []UnwokenDispatchesRow
	for rows.Next() {
		var i UnwokenDispatchesRow
		if err := rows.Scan(&i.ID, &i.WorkflowID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
